all.example:
for (const worldExport of kcds.world.WorldResource.all()) {
  console.info(`${worldExport.name}: ${worldExport.props.length} props from ${worldExport.path}`);
}

all.exampleCs:
foreach (var worldExport in WorldResource.All())
{
    Log.Info($"{worldExport.Name}: {worldExport.Props.Length} props from {worldExport.Path}");
}

find.example:
const market = kcds.world.WorldResource.find('market');
if (market) {
  console.info(market.loaded, market.level);
}

find.exampleCs:
var market = WorldResource.Find("market");
if (market != null)
{
    Log.Info($"{market.Loaded} {market.Level}");
}

items.example:
const harvest = worldExport.items.find((stack) => stack.name === 'harvest');
if (harvest) {
  console.info(`${harvest.amount} left at the market`);
}

items.exampleCs:
var harvest = worldExport.Items.FirstOrDefault(stack => stack.Name == "harvest");
if (harvest != null)
{
    Log.Info($"{harvest.Amount} left at the market");
}

doors.example:
const village = kcds.world.WorldResource.find('village');
const barn = village?.doors.find((door) => door.name === 'barn');
if (barn?.locked) {
  console.info('the barn is locked');
}

doors.exampleCs:
var village = WorldResource.Find("village");
var barn = village?.Doors.FirstOrDefault((door) => door.Name == "barn");
if (barn?.Locked == true)
{
    Log.Info("the barn is locked");
}

smartObjects.example:
const tavern = kcds.world.WorldResource.find('tavern');
const diceTables = tavern?.smartObjects.filter((object) => object.kind === 'dice') ?? [];
console.info(`${diceTables.length} dice tables in the tavern`);

smartObjects.exampleCs:
var tavern = WorldResource.Find("tavern");
var diceTables = tavern?.SmartObjects.Where(@object => @object.Kind == "dice").ToArray() ?? Array.Empty<object>();
Log.Info($"{diceTables.Length} dice tables in the tavern");
